// HasRun applies the HasEdge predicate on the "run" edge.
func HasRun() predicate.EvalCaseResult {
	return predicate.EvalCaseResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RunTable, RunColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunWith applies the HasEdge predicate on the "run" edge with a given conditions (other predicates).
func HasRunWith(preds ...predicate.EvalRun) predicate.EvalCaseResult {
	return predicate.EvalCaseResult(func(s *sql.Selector) {
		step := newRunStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCase applies the HasEdge predicate on the "case" edge.
func HasCase() predicate.EvalCaseResult {
	return predicate.EvalCaseResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CaseTable, CaseColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCaseWith applies the HasEdge predicate on the "case" edge with a given conditions (other predicates).
func HasCaseWith(preds ...predicate.EvalCase) predicate.EvalCaseResult {
	return predicate.EvalCaseResult(func(s *sql.Selector) {
		step := newCaseStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EvalCaseResult) predicate.EvalCaseResult {
	return predicate.EvalCaseResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EvalCaseResult) predicate.EvalCaseResult {
	return predicate.EvalCaseResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EvalCaseResult) predicate.EvalCaseResult {
	return predicate.EvalCaseResult(sql.NotPredicates(p))
}
